def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_moves = [h[0] for h in history]
    op_moves = [h[1] for h in history]
    my_defects = sum(1 for m in my_moves if m == 'D')
    op_defects = sum(1 for o in op_moves if o == 'D')

    retaliations = 0
    forgives = 0
    for i in range(1, n):
        if my_moves[i-1] == 'D':
            if op_moves[i] == 'D':
                retaliations += 1
            else:
                forgives += 1

    if my_defects > 0 and retaliations == 0 and forgives > 0:
        return 'D'

    if op_defects > n * 0.7:
        return 'D'

    if my_defects > 0 and forgives > retaliations * 2:
        if rng.random() < 0.6:
            return 'D'
        else:
            return 'C'

    last_my, last_op = history[-1]

    if last_op == 'D':
        if last_my == 'D':
            dd_run = 0
            for i in range(n-1, -1, -1):
                if my_moves[i] == 'D' and op_moves[i] == 'D':
                    dd_run += 1
                else:
                    break
            if dd_run >= 2 and rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if n >= 2 and my_moves[-2] == 'D':
                return 'C'
            else:
                return 'D'
    else:
        if last_my == 'D':
            return 'C'
        else:
            if n >= 10 and n < 95:
                recent_op = op_moves[-10:]
                if all(o == 'C' for o in recent_op):
                    recent_my = my_moves[-10:]
                    if 'D' not in recent_my:
                        if rng.random() < 0.05:
                            return 'D'
            return 'C'
